@@ -0,0 +1,376 @@
+import { type AnyColumn, Column } from '~/column.ts';
+import { is } from '~/entity.ts';
+import { isSQLWrapper, SQL, type SQLChunk, sql, type SQLWrapper } from '../sql.ts';
+import type { ValueOrArray } from '~/utils.ts';
+
+export type ExpressionDataType<T> = T extends AnyColumn ? T['_']['data']
+	: T extends SQL<infer U> ? U
+	: T extends SQL.Aliased<infer U> ? U
+	: T extends SQLWrapper ? unknown
+	: T;
+
+export interface FrameBoundary extends SQLWrapper {
+	readonly type: 'unbounded_preceding' | 'preceding' | 'current_row' | 'following' | 'unbounded_following';
+	readonly value?: number;
+	readonly offset: number;
+	getSQL(): SQL;
+}
+
+export const unboundedPreceding: FrameBoundary = {
+	type: 'unbounded_preceding',
+	offset: -Infinity,
+	getSQL: () => sql.raw('unbounded preceding'),
+};
+
+export const currentRow: FrameBoundary = {
+	type: 'current_row',
+	offset: 0,
+	getSQL: () => sql.raw('current row'),
+};
+
+export const unboundedFollowing: FrameBoundary = {
+	type: 'unbounded_following',
+	offset: Infinity,
+	getSQL: () => sql.raw('unbounded following'),
+};
+
+export function preceding(offset: number): FrameBoundary {
+	if (typeof offset !== 'number' || !Number.isInteger(offset) || offset < 0) {
+		throw new Error(`preceding() argument must be a non-negative integer, received ${offset}`);
+	}
+	return {
+		type: 'preceding',
+		value: offset,
+		offset: -offset,
+		getSQL: () => sql.raw(`${offset} preceding`),
+	};
+}
+
+export function following(offset: number): FrameBoundary {
+	if (typeof offset !== 'number' || !Number.isInteger(offset) || offset < 0) {
+		throw new Error(`following() argument must be a non-negative integer, received ${offset}`);
+	}
+	return {
+		type: 'following',
+		value: offset,
+		offset: offset,
+		getSQL: () => sql.raw(`${offset} following`),
+	};
+}
+
+export interface FrameSpec {
+	from: FrameBoundary;
+	to?: FrameBoundary;
+}
+
+export class Frame implements SQLWrapper {
+	constructor(
+		readonly type: 'rows' | 'range',
+		readonly spec: FrameSpec,
+	) {
+		if (spec.from.type === 'unbounded_following') {
+			throw new Error('Frame "from" boundary cannot be unbounded following');
+		}
+		if (spec.to !== undefined && spec.to.type === 'unbounded_preceding') {
+			throw new Error('Frame "from" boundary cannot be ordered after "to" boundary');
+		}
+		const toOffset = spec.to !== undefined ? spec.to.offset : 0;
+		if (spec.from.offset > toOffset) {
+			throw new Error('Frame "from" boundary cannot be ordered after "to" boundary');
+		}
+	}
+
+	getSQL(): SQL {
+		if (this.spec.to !== undefined) {
+			return sql`${sql.raw(this.type)} between ${this.spec.from.getSQL()} and ${this.spec.to.getSQL()}`;
+		}
+		return sql`${sql.raw(this.type)} ${this.spec.from.getSQL()}`;
+	}
+}
+
+export function rows(spec: FrameSpec): Frame {
+	return new Frame('rows', spec);
+}
+
+export function range(spec: FrameSpec): Frame {
+	return new Frame('range', spec);
+}
+
+export type WindowOrderByChunk = SQLWrapper | AnyColumn | SQL;
+export type WindowPartitionByChunk = SQLWrapper | AnyColumn | SQL;
+
+export interface WindowSpec {
+	baseWindow?: string;
+	partitionBy?: ValueOrArray<WindowPartitionByChunk>;
+	orderBy?: ValueOrArray<WindowOrderByChunk>;
+	frame?: Frame | SQL | SQLWrapper;
+}
+
+export function buildWindowSpec(spec?: WindowSpec): SQL {
+	if (!spec) {
+		return sql.empty();
+	}
+
+	const parts: SQL[] = [];
+
+	if (spec.baseWindow) {
+		parts.push(sql`${sql.identifier(spec.baseWindow)}`);
+	}
+
+	if (spec.partitionBy !== undefined) {
+		const partitions = Array.isArray(spec.partitionBy) ? spec.partitionBy : [spec.partitionBy];
+		if (partitions.length > 0) {
+			parts.push(sql`partition by ${sql.join(partitions, sql`, `)}`);
+		}
+	}
+
+	if (spec.orderBy !== undefined) {
+		const orders = Array.isArray(spec.orderBy) ? spec.orderBy : [spec.orderBy];
+		if (orders.length > 0) {
+			parts.push(sql`order by ${sql.join(orders, sql`, `)}`);
+		}
+	}
+
+	if (spec.frame !== undefined) {
+		const frameSQL = isSQLWrapper(spec.frame) ? spec.frame.getSQL() : (spec.frame as SQL);
+		parts
